// https://orval.dev/reference/configuration/output#header
// prevent orval version number from being included in generated file header. Otherwise update creates 1000s of changed files
const createHeader = (info: {
    title: string;
    description?: string;
    termsOfService?: string;
    version: string;
}): Array<string> => [
    `Generated by orval 🍺 (with custom config in orval.config.ts)`,
    `Do not edit manually.`,
    ...(info.title ? [info.title] : []),
    ...(info.description ? [info.description] : []),
    ...(info.version ? [`OpenAPI spec version: ${info.version}`] : []),
];

// eslint-disable-next-line unicorn/prefer-module
module.exports = {
    api: {
        output: {
            mode: "split",
            target: "./src/api/api.ts",
            schemas: "./src/api/model",
            client: "react-query",
            urlEncodeParameters: true,
            override: {
                mutator: {
                    path: "./src/api/api-instance.ts",
                    name: "customInstance",
                },
            },
        },
        input: {
            target: "./src/api/api.yaml",
        },
    },
};
